11	        if (tool === "edit_table_blocks") return { ok: true };
12	        if (tool === "inspect_table_blocks") return { book: sent };
13	        throw new Error("unexpected tool");
14	      },
15	    };
16	
17	    const res = await writeBook(sent, client);
18	
19	    expect(res).toEqual({ ok: true, attempts: 1, diffs: [] });
20	    expect(calls.map((c) => c.tool)).toEqual(["edit_table_blocks", "inspect_table_blocks"]);
