28	      async call(tool: string, args: Record<string, unknown>) {
29	        calls.push({ tool, args });
30	        if (tool === "edit_table_blocks") return { ok: true };
31	        if (tool === "inspect_table_blocks") {
32	          inspectCount++;
33	          if (inspectCount === 1) return {};
34	          return { book: sent };
35	        }
36	        throw new Error("unexpected tool");
37	      },
38	    };
39	
40	    const res = await writeBook(sent, client);
41	
42	    expect(res.ok).toBe(true);
43	    expect(res.attempts).toBe(2);
