46	      "edit_table_blocks",
47	      "inspect_table_blocks",
48	      "edit_table_blocks",
49	      "inspect_table_blocks",
50	    ]);
51	  });
52	
53	  it("returns ok false with diffs after one retry when the readback stays different", async () => {
54	    const sent = { value: 1.005 } as any;
55	    const readback = { value: 2.005 } as any;
