78	    const calls: { tool: string; args: Record<string, unknown> }[] = [];
79	    const client = {
80	      async call(tool: string, args: Record<string, unknown>) {
81	        calls.push({ tool, args });
82	        if (tool === "edit_table_blocks") return { ok: true };
83	        if (tool === "inspect_table_blocks") return { book: readback };
84	        throw new Error("unexpected tool");
85	      },
86	    };
87	
88	    const res = await writeBook(sent, client, { retries: 2 });
89	
90	    expect(res.ok).toBe(false);
91	    expect(res.attempts).toBe(3);
92	    expect(calls.filter((c) => c.tool === "edit_table_blocks")).toHaveLength(3);
93	    expect(calls.filter((c) => c.tool === "inspect_table_blocks")).toHaveLength(3);
94	  });
95	
96	  it("does not throw on client errors and counts them as attempts", async () => {
97	    const sent = { value: 1 } as any;
98	    let clientCalls = 0;
99	    const client = {
100	      async call(_tool: string, _args: Record<string, unknown>) {
101	        clientCalls++;
102	        throw new Error("client unavailable");
103	      },
104	    };
105	
106	    const res = await writeBook(sent, client, { retries: 0 });
107	
108	    expect(res.ok).toBe(false);
109	    expect(res.attempts).toBe(1);
110	    expect(clientCalls).toBe(1);
111	  });
112	});
113	
114	describe("diffBook", () => {
115	  it("treats numeric differences within 0.005 as equal", () => {
116	    expect(diffBook({ value: 1.0 } as any, { value: 1.004 } as any)).toEqual([]);
117	    expect(diffBook({ value: 1.0 } as any, { value: 1.005 } as any)).toEqual([]);
118	  });
119	
120	  it("returns a diff when a numeric difference exceeds 0.005", () => {
121	    const diffs = diffBook({ value: 1.0 } as any, { value: 1.006 } as any);
122	
123	    expect(diffs).toHaveLength(1);
124	    expect(diffs[0].path).toContain("value");
