import type { BookOutput as Book } from "./book.ts";

/** The slice of an MCP client writeBook needs: one `call(tool, args)` round trip. */
export type McpClient = {
  call(tool: string, args: Record<string, unknown>): Promise<unknown>;
};

/** One place where the read-back disagrees with what was sent. */
export type BookDiff = { path: string; sent: unknown; got: unknown };

export type WriteBookResult = {
  ok: boolean;
  attempts: number;
  diffs: BookDiff[];
};

/** Numbers that differ by no more than this count as equal. */
const TOLERANCE = 0.005;

export const WRITE_TOOL = "edit_table_blocks";
export const READ_TOOL = "inspect_table_blocks";

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

const isAbsent = (v: unknown): boolean => v === null || v === undefined;

const sameScalar = (sent: unknown, got: unknown): boolean => {
  if (typeof sent === "number" && typeof got === "number") {
    if (Number.isNaN(sent) && Number.isNaN(got)) return true;
    return Math.abs(sent - got) <= TOLERANCE;
  }
  if (isAbsent(sent) || isAbsent(got)) return isAbsent(sent) && isAbsent(got);
  return sent === got;
};

function collect(path: string, sent: unknown, got: unknown, out: BookDiff[]): void {
  if (Array.isArray(sent) || Array.isArray(got)) {
    if (!Array.isArray(sent) || !Array.isArray(got)) {
      out.push({ path, sent, got });
      return;
    }
    const length = Math.max(sent.length, got.length);
    for (let i = 0; i < length; i++) {
      collect(`${path}[${i}]`, sent[i], got[i], out);
    }
    return;
  }
  if (isRecord(sent) && isRecord(got)) {
    const keys = Object.keys(sent);
    for (const key of Object.keys(got)) if (!(key in sent)) keys.push(key);
    for (const key of keys) {
      collect(path === "" ? key : `${path}.${key}`, sent[key], got[key], out);
    }
    return;
  }
  if (!sameScalar(sent, got)) out.push({ path, sent, got });
}

/** Every path where the read-back differs from what was sent. Numbers compare within 0.005. */
export function diffBook(sent: Book, readback: Book): BookDiff[] {
  const diffs: BookDiff[] = [];
  collect("", sent, readback, diffs);
  return diffs;
}

/** The read-back arrives as a Book-shaped object at `result.book`; absent means empty. */
const readbackOf = (result: unknown): Book =>
  isRecord(result) && isRecord(result.book) ? (result.book as Book) : ({} as Book);

/**
 * Write the book through the cfo.ai MCP, then read it back and diff it.
 * On a mismatch the write is retried (`opts.retries`, default 1). Client errors count
 * as an attempt and are never thrown; they leave `diffs` empty for that attempt.
 */
export async function writeBook(
  book: Book,
  client: McpClient,
  opts: { retries?: number } = {},
): Promise<WriteBookResult> {
  const budget = Math.max(0, Math.floor(opts.retries ?? 1)) + 1;
  let attempts = 0;
  let diffs: BookDiff[] = [];

  for (let i = 0; i < budget; i++) {
    attempts++;
    try {
      await client.call(WRITE_TOOL, { book });
      const result = await client.call(READ_TOOL, {});
      diffs = diffBook(book, readbackOf(result));
      if (diffs.length === 0) return { ok: true, attempts, diffs: [] };
    } catch {
      diffs = [];
    }
  }

  return { ok: false, attempts, diffs };
}

