import { expect, test } from "bun:test";
import { buildBook, type BookOutput } from "../src/cfo/book.ts";
import { diffBook, writeBook } from "../src/cfo/mcp.ts";

type Call = { tool: string; args: Record<string, unknown> };

/** The book we actually send: two setups plus the promoted one that drives the scenario. */
const book = (): BookOutput =>
  buildBook({
    periodDays: 15,
    setups: [
      { id: "a", label: "A", costUsd: 30, sessions: 10, survivingChanges: 6, unattendedShare: 0.5555 },
      { id: "b", label: "B", costUsd: null, sessions: 4, survivingChanges: 0, unattendedShare: 0 },
    ],
    promoted: "a",
    assumptions: { engineerMonthlyLoadedUsd: 15000, scaleSessionsPerWeek: 70 },
  });

/** A client that serves writes from `ok` and read-backs from `reads`, one per inspect. */
const client = (
  reads: unknown[],
  calls: Call[] = [],
): { call(tool: string, args: Record<string, unknown>): Promise<unknown> } => {
  let i = 0;
  return {
    async call(tool, args) {
      calls.push({ tool, args });
      if (tool === "edit_table_blocks") return { ok: true };
      if (tool === "inspect_table_blocks") return reads[Math.min(i++, reads.length - 1)];
      throw new Error(`unexpected tool ${tool}`);
    },
  };
};

test("matching read-back writes once and reads once", async () => {
  const sent = book();
  const calls: Call[] = [];
  const res = await writeBook(sent, client([{ book: sent }], calls));

  expect(res).toEqual({ ok: true, attempts: 1, diffs: [] });
  expect(calls.map((c) => c.tool)).toEqual(["edit_table_blocks", "inspect_table_blocks"]);
  expect(calls[0]?.args).toEqual({ book: sent });
});

test("numbers just outside the tolerance are a mismatch", async () => {
  const sent = book();
  const readback = book();
  readback.scenario.scaleMonthlyUsd = sent.scenario.scaleMonthlyUsd! + 0.006;

  const res = await writeBook(sent, client([{ book: readback }]));

  expect(res.ok).toBe(false);
  expect(res.diffs).toEqual([
    {
      path: "scenario.scaleMonthlyUsd",
      sent: sent.scenario.scaleMonthlyUsd,
      got: sent.scenario.scaleMonthlyUsd! + 0.006,
    },
  ]);
});

test("a number within the tolerance is not a mismatch", () => {
  expect(diffBook(book(), book())).toEqual([]);
  const nudged = book();
  nudged.department[0]!.costPerSurvivingChangeUsd = nudged.department[0]!.costPerSurvivingChangeUsd! + 0.005;
  expect(diffBook(book(), nudged)).toEqual([]);
});

test("a missing read-back is empty, so it retries once and can still succeed", async () => {
  const sent = { value: 1.005 } as unknown as BookOutput;
  const calls: Call[] = [];
  const res = await writeBook(sent, client([{}, { book: sent }], calls));

  expect(res).toEqual({ ok: true, attempts: 2, diffs: [] });
  expect(calls.map((c) => c.tool)).toEqual([
    "edit_table_blocks",
    "inspect_table_blocks",
    "edit_table_blocks",
    "inspect_table_blocks",
  ]);
});

